      "poi_id": "p63",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "Bánh căn giòn rụm, nước chấm thơm lừng — ngon quá (so tasty) là phải thốt lên."
    },
    {
      "poi_id": "p90",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thác đổ trắng xóa giữa rừng thông, đứng gần là mát lạnh cả người."
    },
    {
      "poi_id": "p173",
      "kind": "activity",
      "must_do_id": null,
      "note": "Mặt hồ phẳng như gương, ngồi ngắm mây trôi là hết muộn phiền."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tiếng chuông chùa ngân trong gió núi, lòng nhẹ tênh như đang bay."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ ấm cúng, món ăn bày đẹp như tranh, ngồi xuống là muốn nán lại."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm rực rỡ, đi một vòng là đủ thấy hết vị Đà Lạt."
    }
  ]
}
```

